onlineRoom(room){
    if(!personalProfiles)personalProfiles=profiles.map(p=>({...p}));
    const key=JSON.stringify(room.players.map(p=>[p.id,p.name,p.avatar,p.vehicle]));
    if(key!==onlineProfileKey){onlineProfileKey=key;profiles=C.cleanProfiles(null);for(const p of room.players){const original=C.cleanProfiles(null)[p.avatar];profiles[p.id]={...original,name:p.name,photo:globalThis.KartPortraits[p.avatar]};}renderer.setProfiles(profiles);}
    $('connectionBadge').hidden=false;
    if(room.phase==='lobby'&&onlineRound){onlineRound='';onlinePaused=false;screen='menu';mode='race';cup=null;resultHandled=false;all('dialog[open]').forEach(d=>d.close());$('hud').hidden=true;$('menu').hidden=false;makeDemo();updateMenu();$('friendsDialog').showModal();}
    if($('resultsDialog').open&&room.phase==='results'){$('resultNext').disabled=room.hostId!==network.id;$('resultNext').textContent=room.hostId===network.id?'Back to the room →':'Waiting for the host';}
  }
  function onlineSnapshot(state,id){
    if(!network?.room)return;
    const key=network.room.epoch+':'+state.round;
    if(onlineRound!==key){
      onlineRound=key;all('dialog[open]').forEach(d=>d.close());onlinePaused=false;mode='online';cup=null;trackId=state.track;
      race=C.newRace({track:state.track,driver:0,difficulty:network.room.difficulty});race.multiplayer=true;race.mode='online';race.racers=state.racers.map(p=>({...p})).sort((a,b)=>(a.id===id?-1:b.id===id?1:a.id-b.id));
      race.countdown=state.countdown;race.time=state.time;race.phase=state.phase;race.inputs={};renderer.setTrack(race.track);screen='race';resultHandled=false;eventCount=0;lastCount=-1;toastUntil=0;accumulator=0;clearInput();
      $('menu').hidden=true;$('hud').hidden=false;$('raceToast').classList.remove('visible');$('hudTrack').textContent='ROOM '+network.room.code+' · '+race.track.name;updateTouch();audio.unlock();
    }
  }
  function onlineLeave(){
    onlineRound='';onlinePaused=false;onlineProfileKey='';if(personalProfiles){profiles=personalProfiles;personalProfiles=null;renderer.setProfiles(profiles);}mode='race';$('connectionBadge').hidden=true;$('settingsRoomLabel').textContent='Create a room or join with four digits.';$('settingsInvite').value=new URL('/games/wacky-races/',location.href).href;home();
  }
