/* Square cartoon tiles and online room controls. */
.avatar,.driver-card .avatar{border-radius:8px!important;overflow:hidden!important;aspect-ratio:1}
.avatar img{width:100%;height:100%;object-fit:cover}.friends-dialog{max-width:760px;width:min(94vw,760px)}
.friends-dialog h2{margin-bottom:0}.friends-status{padding:10px 12px;background:#e5f3ec;border-radius:9px;line-height:1.45;font-size:13px}
.friend-details{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:10px}.friends-dialog label,.invite-label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700}
.friends-dialog input:not([type=checkbox]),.friends-dialog select,.invite-label input{box-sizing:border-box;width:100%;padding:10px;border:1px solid #b9cbbb;border-radius:8px;background:#fffdf3;color:#173c4c;font:500 14px system-ui;min-height:43px}
.room-entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:14px}.room-entry-grid form{padding:16px;background:#f4efd9;border:1px solid #d3d8bc;border-radius:14px}.room-entry-grid h3{margin-top:0}.room-entry-grid p{font-size:12px;line-height:1.5}.room-entry-grid button{margin-top:14px}#roomCodeInput{font:800 27px ui-monospace,monospace;letter-spacing:8px;text-align:center;padding:5px}
.room-code-card{display:flex;align-items:center;flex-direction:column;background:#193d50;color:#fff3cd;border-radius:16px;padding:14px;margin:12px 0}.room-code-card>span{font-size:11px;letter-spacing:1px}.room-code-card>strong{font:900 52px ui-monospace,monospace;letter-spacing:14px;padding-left:14px}.room-players{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}.friend-player{display:flex;align-items:center;gap:8px;padding:8px;background:#eeeeda;border-radius:10px;min-width:0}.friend-player img{width:38px;height:38px;border-radius:4px}.friend-player strong{font-size:12px;flex:1;overflow-wrap:anywhere}.friend-player>span{font-size:10px;color:#806644}.friend-player .ready{color:#1a704a;font-weight:800}
.share-room{margin-top:18px}.invite-label{margin-top:12px}.invite-label input{font-size:12px}.friends-settings{padding:15px;margin-bottom:16px;background:#fff0be;border-radius:14px}.friends-settings h3{margin:0}.friends-settings p{font-size:12px;line-height:1.5}.connection-badge{position:fixed;top:100px;left:50%;transform:translateX(-50%);padding:5px 12px;background:#17483ddd;color:#d7ffd8;border-radius:7px;font:700 11px system-ui;z-index:6;pointer-events:none}.connection-badge.offline{background:#64391de8;color:#fff0ce}
@media(max-width:640px){.friend-details{grid-template-columns:1fr 1fr}.friend-details label:first-child{grid-column:1/-1}.room-entry-grid{grid-template-columns:1fr}.room-players{grid-template-columns:1fr}.friends-dialog{padding:20px!important;max-height:90dvh}.topbar nav .nav-button{padding:8px 6px!important;font-size:10px!important}.connection-badge{top:92px;max-width:60vw;text-align:center}.room-code-card>strong{font-size:43px}}
@media(max-height:540px) and (orientation:landscape){.friends-dialog{max-height:94dvh}.room-entry-grid{grid-template-columns:1fr 1fr}.friend-details{grid-template-columns:1.2fr 1fr 1fr}.friend-details label:first-child{grid-column:auto}.room-players{grid-template-columns:1fr 1fr}.connection-badge{top:82px}}
